// Motif d'arriere-plan des pages d'authentification.
// Image integree directement en base64 dans le code : aucun fichier separe
// dans public/ n'est necessaire, donc rien ne peut se perdre ou etre corrompu au transfert.

const BASE = '#565b5f'; // meme gris que la sidebar du Dashboard

const AUTH_BG = "data:image/jpeg;base64,";

export default function AuthBackground() {
  return (
    <div
      aria-hidden="true"
      className="pointer-events-none absolute inset-0 h-full w-full"
      style={{
        backgroundColor: BASE,
        backgroundImage: 'url(' + AUTH_BG + ')',
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        backgroundRepeat: 'no-repeat',
        backgroundBlendMode: 'multiply',
      }}
    />
  );
}
